create extension if not exists pgcrypto;
create table if not exists public.parent_accounts(id uuid primary key references auth.users(id) on delete cascade,display_name text,created_at timestamptz not null default now());
create table if not exists public.child_profiles(id uuid primary key default gen_random_uuid(),parent_id uuid not null references public.parent_accounts(id) on delete cascade,nickname text not null check(char_length(nickname) between 1 and 24),birth_year smallint,preferred_language text not null default 'en' check(preferred_language in('en','te','both')),created_at timestamptz not null default now());
create table if not exists public.subjects(id text primary key,name_en text not null,name_te text not null,icon text not null);
create table if not exists public.topics(id uuid primary key default gen_random_uuid(),subject_id text not null references public.subjects(id),age_min smallint not null check(age_min between 1 and 10),age_max smallint not null check(age_max between age_min and 10),title_en text not null,title_te text not null);
create table if not exists public.questions(id uuid primary key default gen_random_uuid(),topic_id uuid references public.topics(id),age_min smallint not null check(age_min between 1 and 10),age_max smallint not null check(age_max between age_min and 10),question_type text not null check(question_type in('picture-choice','audio-choice','multiple-choice','true-false','matching','puzzle')),prompt_en text not null,prompt_te text not null,choices jsonb not null default '[]',correct_answer jsonb not null,explanation_en text,explanation_te text,reviewed boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.quiz_attempts(id uuid primary key default gen_random_uuid(),child_id uuid not null references public.child_profiles(id) on delete cascade,subject_id text not null references public.subjects(id),age_band text not null,score integer not null default 0,total_questions integer not null default 0,completed_at timestamptz not null default now());
create table if not exists public.learning_progress(child_id uuid not null references public.child_profiles(id) on delete cascade,subject_id text not null references public.subjects(id),questions_answered integer not null default 0,correct_answers integer not null default 0,updated_at timestamptz not null default now(),primary key(child_id,subject_id));
create table if not exists public.achievements(id uuid primary key default gen_random_uuid(),child_id uuid not null references public.child_profiles(id) on delete cascade,achievement_code text not null,awarded_at timestamptz not null default now(),unique(child_id,achievement_code));
create table if not exists public.parental_settings(child_id uuid primary key references public.child_profiles(id) on delete cascade,daily_limit_minutes smallint not null default 30 check(daily_limit_minutes between 5 and 180),audio_enabled boolean not null default true,updated_at timestamptz not null default now());
alter table public.parent_accounts enable row level security;alter table public.child_profiles enable row level security;alter table public.quiz_attempts enable row level security;alter table public.learning_progress enable row level security;alter table public.achievements enable row level security;alter table public.parental_settings enable row level security;
create policy "parent reads own account" on public.parent_accounts for select using(id=auth.uid());
create policy "parent inserts own account" on public.parent_accounts for insert with check(id=auth.uid());
create policy "parent updates own account" on public.parent_accounts for update using(id=auth.uid()) with check(id=auth.uid());
create policy "parents manage own child profiles" on public.child_profiles for all using(parent_id=auth.uid()) with check(parent_id=auth.uid());
create policy "parents read own attempts" on public.quiz_attempts for select using(exists(select 1 from public.child_profiles c where c.id=child_id and c.parent_id=auth.uid()));
create policy "parents insert own attempts" on public.quiz_attempts for insert with check(exists(select 1 from public.child_profiles c where c.id=child_id and c.parent_id=auth.uid()));
create policy "parents read own progress" on public.learning_progress for select using(exists(select 1 from public.child_profiles c where c.id=child_id and c.parent_id=auth.uid()));
create policy "parents manage own progress" on public.learning_progress for all using(exists(select 1 from public.child_profiles c where c.id=child_id and c.parent_id=auth.uid())) with check(exists(select 1 from public.child_profiles c where c.id=child_id and c.parent_id=auth.uid()));
create policy "parents read own achievements" on public.achievements for select using(exists(select 1 from public.child_profiles c where c.id=child_id and c.parent_id=auth.uid()));
create policy "parents insert own achievements" on public.achievements for insert with check(exists(select 1 from public.child_profiles c where c.id=child_id and c.parent_id=auth.uid()));
create policy "parents manage own settings" on public.parental_settings for all using(exists(select 1 from public.child_profiles c where c.id=child_id and c.parent_id=auth.uid())) with check(exists(select 1 from public.child_profiles c where c.id=child_id and c.parent_id=auth.uid()));
alter table public.subjects enable row level security;alter table public.topics enable row level security;alter table public.questions enable row level security;
create policy "public reads subjects" on public.subjects for select using(true);
create policy "public reads topics" on public.topics for select using(true);
create policy "public reads reviewed questions" on public.questions for select using(reviewed=true);
